/** Result line under a form. Green on success, red on failure — never both. */
function Result({ ok, error, okText = "Saved" }: { ok?: boolean; error?: string; okText?: string }) {
  if (error) {
    return <p className="rounded-[9px] border border-red-500/35 bg-red-500/10 px-3 py-2 text-[12.5px] text-red-300">{error}</p>;
  }
  if (ok) return <p className="text-[12.5px] font-semibold text-emerald-400">{okText} ✓</p>;
  return null;
}

function Toggle({ name, defaultChecked, label }: { name: string; defaultChecked: boolean; label: string }) {
  const [on, setOn] = useState(defaultChecked);
  return (
    <span className="relative inline-flex flex-none items-center">
      <input
        type="checkbox"
        name={name}
        aria-label={label}
        checked={on}
        onChange={(e) => setOn(e.target.checked)}
