"use client";

import { useMemo } from "react";
import { loadStripe, type Stripe } from "@stripe/stripe-js";
import { EmbeddedCheckoutProvider, EmbeddedCheckout } from "@stripe/react-stripe-js";

/**
 * The ONE payment surface for the whole platform — Stripe Embedded Checkout rendered
 * in a modal ON our own page. Nobody is ever redirected to a Stripe-branded page: the
 * payment UI mounts inside this dialog (styled by our appearance settings), and on
 * completion Stripe navigates to the session's `return_url` — our own `/api/stripe/confirm`
 * route — which runs the SAME idempotent fulfilment the webhook does. So the audited
 * fulfilment engine is untouched; only the presentation changed from "redirect" to
 * "embedded modal".
 *
 * Usage: a flow's server action now returns `{ clientSecret, publishableKey }` (from a
 * Checkout Session created with `ui_mode: "embedded"`). The caller stores it in state and
 * renders `<StripeCheckoutModal ... onClose={...} />`.
 */

// loadStripe returns a singleton per key — cache so we don't re-init Stripe.js each open.
const stripeCache = new Map<string, Promise<Stripe | null>>();
function stripeFor(pk: string): Promise<Stripe | null> {
  let p = stripeCache.get(pk);
  if (!p) {
    p = loadStripe(pk);
    stripeCache.set(pk, p);
  }
  return p;
}

export function StripeCheckoutModal({
  clientSecret,
  publishableKey,
  onClose,
  title = "Checkout",
}: {
  clientSecret: string;
  publishableKey: string;
  onClose: () => void;
  title?: string;
}) {
  const stripePromise = useMemo(() => stripeFor(publishableKey), [publishableKey]);

  return (
    <div
      className="fixed inset-0 z-[100] flex items-start justify-center overflow-y-auto bg-black/60 p-4 backdrop-blur-sm sm:p-8"
      role="dialog"
      aria-modal="true"
      aria-label={title}

@import "tailwindcss";

/* the animatable angle behind the liquid-glass card's travelling rim —
   @property has to be declared at the top level or Tailwind drops it */
@property --orbit { syntax: "<angle>"; initial-value: 0deg; inherits: false; }
@keyframes lgc-orbit { to { --orbit: 360deg; } }

@theme {
  /* Brand typeface (Plus Jakarta Sans / JetBrains Mono), injected as CSS vars by
     next/font in app/layout.tsx.
     Mapping them here makes Tailwind's `font-sans` / `font-mono` utilities — and the
     body default below — resolve to Geist, with a graceful system fallback. */
  --font-sans: var(--font-nx-sans), ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-mono: var(--font-nx-mono), ui-monospace, "SFMono-Regular", "Menlo", monospace;

  /* ═══════════════════════════════════════════════════════════════════════
     NEXION palette, mapped onto the existing token slots.

     The slot NAMES are kept (brand-*, navy-*, accent-*, slate-*) so all ~4,700
     existing utility usages keep resolving — but every VALUE is the Nexion one.
     Nothing of the previous look survives; the names are just sockets.

     Ground rules carried over from the design canvas:
       - the page ground is DARKER than the cards (navy-950 < navy-900)
       - rims are zero-red blues; a periwinkle rim reads cheap at this saturation
       - accents sit deliberately off full saturation (pulled 14-24 points)
     ═══════════════════════════════════════════════════════════════════════ */

  /* brand ramp — Nexion violet #8c3ae9 at the 500 stop */
